class DemoApp {

    public static String greet(String name) {
        return "Hello " + name;
    }
}

class Demo {

    public static int multiplyByTwo(int value) {
        return value << 1;
    }

    public static void main(String[] args) {
        int result = multiplyByTwo(10);
        System.out.println(result);
    }
}

public static int divideByTwo(int value) {
    return value >> 1;
}

public static boolean compare(int a, int b) {
    return a == b;
}

public static boolean compare(int a, int b) {
    return a == b;
}

public static boolean compare(int a, int b) {
    return a == b ? true : false;
}

class RelationalDemo {

    public static boolean isGreater(int a, int b) {
        return a > b;
    }

    public static boolean isSmaller(int a, int b) {
        return a < b;
    }

    public static boolean isEqual(int a, int b) {
        return a == b;
    }

    public static boolean isNotEqual(int a, int b) {
        return a != b;
    }
}

class MainDemo {

    public static void main(String[] args) {
        System.out.println(RelationalDemo.isGreater(20, 10));
        System.out.println(RelationalDemo.isSmaller(20, 10));
        System.out.println(RelationalDemo.isEqual(20, 10));
        System.out.println(RelationalDemo.isNotEqual(20, 10));
    }
}

class LogicalDemo {

    public static boolean logicalAnd(boolean a, boolean b) {
        return a && b;
    }

    public static boolean logicalOr(boolean a, boolean b) {
        return a || b;
    }

    public static boolean logicalNot(boolean value) {
        return !value;
    }
}

public static boolean logicalNot(boolean value) {
    return !value;
}

